#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=13
ENV_FILE=".dev.vars"   # local dev secrets (gitignored); production copies go to Cloudflare in stage 9
CF_ENV_FILE=".cloudflare.env"   # Cloudflare API token for headless servers (gitignored, never deployed)
cd "$(dirname "$0")/.."

# On a server with no desktop (e.g. over SSH), opening a browser here either fails or starts a
# text browser inside this terminal. Print the link to open on your own computer instead.
HEADLESS=0
if [[ -n "${SSH_CONNECTION:-}${SSH_TTY:-}" ]] ||
   [[ "$(uname)" == Linux && -z "${DISPLAY:-}${WAYLAND_DISPLAY:-}" ]] && ! command -v wslview >/dev/null 2>&1; then
  HEADLESS=1
  open_url() {
    printf '  %s↗ open on your computer:%s %s\n' "$GREEN" "$RESET" "$1"
  }
fi

# Values for Cloudflare go in their own file so they never become Worker bindings via .dev.vars.
cf_ask() { local f="$ENV_FILE"; ENV_FILE="$CF_ENV_FILE"; "$@"; ENV_FILE="$f"; }
if [[ -f "$CF_ENV_FILE" ]]; then
  set -a; . "./$CF_ENV_FILE"; set +a
fi

banner "Lejar: go live on workers.dev"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: sign in"
if npx wrangler whoami 2>/dev/null | grep -qE "You are logged in|associated with"; then
  say "Already signed in to Cloudflare:"
  npx wrangler whoami 2>/dev/null | grep -E "logged in|associated with|│" | head -6 || true
elif (( HEADLESS )); then
  say "This machine has no browser, so 'wrangler login' can't finish here. Use an API token instead."
  open_url "https://dash.cloudflare.com/profile/api-tokens"
  step "Create Token → use the 'Edit Cloudflare Workers' template."
  step "Under Permissions, also add: Account → D1 → Edit, and Account → Workers R2 Storage → Edit."
  step "Account Resources: your account. Zone Resources: All zones (or any). Continue → Create Token → copy it."
  cf_ask ask_secret CLOUDFLARE_API_TOKEN "Paste the API token:"
  open_url "https://dash.cloudflare.com/"
  step "Your Account ID is on the account home page (right-hand side, or in the URL after dash.cloudflare.com/)."
  cf_ask ask CLOUDFLARE_ACCOUNT_ID "Paste the Account ID:"
  cf_ask write_env CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
  cf_ask write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
  export CLOUDFLARE_API_TOKEN CLOUDFLARE_ACCOUNT_ID
  if npx wrangler whoami 2>/dev/null | grep -qE "API Token|associated with|Account"; then
    say "${GREEN}✓${RESET} Wrangler can use the token."
  else
    warn "Wrangler didn't accept the token; check its permissions and re-run."
    exit 1
  fi
else
  say "Wrangler will open a browser to sign in to your Cloudflare account."
  step "Approve the access request in the browser, then come back here."
  npx wrangler login
fi
pause "Signed in? Press Enter"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: enable R2 (receipt photos)"
say "R2 needs a payment card on the account, even on the free tier (10 GB free)."
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "If you see 'Purchase R2 Plan' / 'Add R2 subscription', follow it and add a card."
step "If you see the R2 bucket list instead, R2 is already enabled."
pause "R2 enabled? Press Enter"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: production database (D1)"
d1_id() {
  npx wrangler d1 list --json 2>/dev/null |
    python3 -c 'import sys,json; print(next((d["uuid"] for d in json.load(sys.stdin) if d["name"]=="lejar"), ""))' 2>/dev/null || true
}
DB_ID=$(d1_id)
if [[ -n "$DB_ID" ]]; then
  say "Found the existing D1 database 'lejar' ($DB_ID)."
elif confirm "Create the D1 database 'lejar' now?"; then
  note "If Wrangler offers to add it to your config, answer No: this wizard does that."
  npx wrangler d1 create lejar
  DB_ID=$(d1_id)
fi
if [[ -z "$DB_ID" ]]; then
  warn "No database id; re-run the wizard once 'npx wrangler d1 create lejar' has worked."
  exit 1
fi
if grep -q '"database_id": "local-placeholder"' wrangler.jsonc; then
  sed -i.bak "s/\"database_id\": \"local-placeholder\"/\"database_id\": \"$DB_ID\"/" wrangler.jsonc && rm -f wrangler.jsonc.bak
  printf '  %s✓ wrote%s database_id → wrangler.jsonc\n' "$GREEN" "$RESET"
else
  note "wrangler.jsonc already has a database_id: $(grep -oE '"database_id": "[^"]+"' wrangler.jsonc)"
fi
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: receipt bucket (R2)"
if npx wrangler r2 bucket list 2>/dev/null | grep -qE "(^|[^a-z-])lejar-receipts([^a-z-]|$)"; then
  say "The bucket 'lejar-receipts' already exists."
elif confirm "Create the private R2 bucket 'lejar-receipts' now?"; then
  npx wrangler r2 bucket create lejar-receipts
fi
note "It stays private: the app serves photos to their owner only. Don't turn on public access."
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: database tables"
say "Applies migrations/0001…0004 to the production database."
if confirm "Apply migrations to the REMOTE database now?"; then
  npx wrangler d1 migrations apply lejar --remote
fi
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: first deploy (to get the app's address)"
say "Deploys once so Google can be given the real callback address. Sign-in won't work until stage 9."
deploy_url() { npx wrangler deploy 2>&1 | tee /dev/stderr | grep -oE 'https://lejar\.[a-z0-9-]+\.workers\.dev' | head -1; }
APP_URL=$(deploy_url || true)
if [[ -z "$APP_URL" ]]; then
  warn "Couldn't spot the workers.dev address in the deploy output."
  ask APP_URL "Paste it (https://lejar.<subdomain>.workers.dev):"
fi
APP_URL="${APP_URL%/}"
say "App address: ${BOLD}$APP_URL${RESET}"
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Google: OAuth client"
open_url "https://console.cloud.google.com/auth/clients/create"
step "Pick (or create) a Google Cloud project at the top. The Hermes Gmail project is fine to reuse."
step "If asked to configure the consent screen first: App name 'Lejar', your email as support"
note "  and contact email, Audience 'External'. Then come back to Clients → Create client."
step "Application type: Web application. Name: Lejar."
step "Authorized redirect URIs → add both:"
note "    http://localhost:8787/auth/google/callback"
note "    $APP_URL/auth/google/callback"
step "Create, then copy the Client ID and Client secret from the dialog."
note "(If the console looks different: APIs & Services → Credentials → Create credentials → OAuth client ID.)"
ask GOOGLE_CLIENT_ID "Paste the Client ID:"
ask_secret GOOGLE_CLIENT_SECRET "Paste the Client secret:"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Other secrets: session key, OpenRouter, contact email"
SESSION_SECRET=$(_existing SESSION_SECRET || true)
if [[ -z "$SESSION_SECRET" ]]; then
  SESSION_SECRET=$(openssl rand -base64 32)
  say "Generated a new random SESSION_SECRET."
else
  say "Keeping the existing SESSION_SECRET (changing it signs everyone out)."
fi
write_env SESSION_SECRET "$SESSION_SECRET"
open_url "https://openrouter.ai/settings/keys"
step "Create Key → name it 'lejar'. Consider a credit limit (e.g. \$5) as a second bill guard."
ask_secret OPENROUTER_API_KEY "Paste the OpenRouter key (sk-or-…):"
write_env OPENROUTER_API_KEY "$OPENROUTER_API_KEY"
ask CONTACT_EMAIL "Contact email shown on /privacy:"
write_env CONTACT_EMAIL "$CONTACT_EMAIL"
pause

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: production secrets"
say "Copies the five values to the deployed Worker as encrypted secrets."
if confirm "Set GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET, SESSION_SECRET, OPENROUTER_API_KEY, CONTACT_EMAIL on Cloudflare?"; then
  for name in GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET SESSION_SECRET OPENROUTER_API_KEY CONTACT_EMAIL; do
    if printf '%s' "${!name}" | npx wrangler secret put "$name" >/dev/null 2>&1; then
      printf '  %s✓ set%s Cloudflare secret %s\n' "$GREEN" "$RESET" "$name"
    else
      SKIPPED+=("Cloudflare secret $name (npx wrangler secret put $name)")
      warn "couldn't set $name; run: npx wrangler secret put $name"
    fi
  done
fi
pause

# ── 10 ───────────────────────────────────────────────────────────────────
stage "Deploy and check"
npx wrangler deploy
HEALTH=$(curl -fsS "$APP_URL/healthz" 2>/dev/null || true)
ROOT=$(curl -s -o /dev/null -w '%{http_code} %{redirect_url}' "$APP_URL/" || true)
if [[ "$HEALTH" == "ok" ]]; then say "${GREEN}✓${RESET} /healthz returns ok"; else warn "/healthz returned '$HEALTH'"; SKIPPED+=("/healthz check"); fi
if [[ "$ROOT" == 302*"/login" ]]; then say "${GREEN}✓${RESET} / redirects to /login when signed out"; else warn "/ returned '$ROOT'"; SKIPPED+=("sign-in redirect check"); fi
step "Now sign in at $APP_URL from your computer's browser (you're a test user while the app is in Testing)."
open_url "$APP_URL"
pause "Signed in and saw the dashboard? Press Enter"

# ── 11 ───────────────────────────────────────────────────────────────────
stage "Google: open sign-in to everyone"
open_url "https://console.cloud.google.com/auth/branding"
step "Branding → App home page: $APP_URL/"
step "Branding → Privacy policy link: $APP_URL/privacy"
step "Data access → scopes should be only openid and .../auth/userinfo.email (non-sensitive)."
step "Audience → Publish app → Confirm."
warn "Google may require the home page and privacy URLs to be on a domain you've verified."
note "  You can't verify workers.dev. If Google refuses, either keep the app in Testing (add each"
note "  person as a test user, up to 100) or put Lejar on a custom domain and use that instead."
if confirm "Did publishing succeed?"; then say "Anyone with a verified Google account can now sign in."
else SKIPPED+=("publish the Google consent screen (see the workers.dev note)"); fi
pause

# ── 12 ───────────────────────────────────────────────────────────────────
stage "Commit the production database id"
git --no-pager diff --stat -- wrangler.jsonc || true
if ! git diff --quiet -- wrangler.jsonc && confirm "Commit wrangler.jsonc with the database id?"; then
  git add wrangler.jsonc && git commit -q -m "Configure production D1 id" && say "${GREEN}✓${RESET} committed"
else
  note "Nothing to commit, or skipped."
fi
pause

# ── 13 ───────────────────────────────────────────────────────────────────
stage "iPhone: end to end"
say "On your iPhone, in Safari, open: ${BOLD}$APP_URL${RESET}"
step "Sign in with Google."
step "Share → Add to Home Screen, then open Lejar from the Home Screen icon."
step "Add a vehicle, open its schedule, and set one 'last done' baseline."
step "Scan a real workshop receipt: check the photo shrinks/uploads and fields prefill, then Save."
step "Check the dashboard shows due items, road tax and insurance."
step "Open the vehicle → Print / PDF → Share → Print → save as PDF."
note "If a scan comes back 'Couldn't read receipt', run: npx wrangler tail   (it logs why)."
if ! confirm "Everything worked on the iPhone?"; then SKIPPED+=("iPhone end-to-end check"); fi

finish
say "Lejar is live at $APP_URL"
}

run_wizard "$@"; exit
